"use client";

import { useEffect, useMemo, useState } from "react";
import { Bot, CalendarDays, ChevronDown, ChevronLeft, CirclePlus, ContactRound, Database, Download, Eye, Filter, MoreVertical, Pencil, Phone, Plus, RefreshCw, Search, Settings2, Trash2, Type, UserPlus, X } from "lucide-react";
import { Bar, BarChart, CartesianGrid, ResponsiveContainer, Tooltip, XAxis, YAxis } from "recharts";
import type { DashboardDataset } from "./dashboard-shell";

const control = "h-11 rounded-xl border border-[#d9dee7] bg-white px-3 text-sm outline-none focus:border-[#1f7659] focus:ring-4 focus:ring-[#1f765915]";

export function RetellAgentsView({ agents }: { agents: DashboardDataset["agents"] }) {
  const [search, setSearch] = useState(""); const [selected, setSelected] = useState<string | null>(null);
  const rows = agents.filter((agent) => agent.name.toLowerCase().includes(search.toLowerCase()));
  return <div className="glass overflow-hidden rounded-2xl"><div className="flex flex-col gap-3 border-b p-5 sm:flex-row sm:items-center"><h2 className="font-semibold">Agents</h2><label className="relative sm:ml-auto"><Search className="absolute left-3 top-1/2 size-4 -translate-y-1/2 text-[#84928d]"/><input value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Search agents" className={`${control} pl-10`}/></label></div><div className="overflow-x-auto"><table className="w-full min-w-[760px] text-left"><thead><tr className="bg-[#f0f3f7] text-xs text-[#596a7a]"><th className="p-4">Agent Name</th><th className="p-4">Agent Type</th><th className="p-4">Channel</th><th className="p-4">Sessions</th><th className="p-4">Status</th><th className="p-4">Last synchronized</th><th/></tr></thead><tbody>{rows.map((agent) => <tr key={agent.id} className="border-b last:border-0"><td className="p-4"><div className="flex items-center gap-3"><span className="grid size-10 place-items-center rounded-xl bg-[#f1f3f8]"><Bot className="size-5 text-[#1f7659]"/></span><span className="font-semibold">{agent.name}</span></div></td><td className="p-4"><span className="rounded-full bg-[#f1f3f8] px-3 py-1 text-xs font-semibold">Managed agent</span></td><td className="p-4 capitalize">{agent.kind}</td><td className="p-4">{agent.kind === "voice" ? agent.calls : agent.chats}</td><td className="p-4 capitalize">{agent.status}</td><td className="p-4 text-sm text-[#71817c]">{agent.modifiedAt ? new Date(agent.modifiedAt).toLocaleString() : "Provider synchronized"}</td><td className="p-4"><button onClick={() => setSelected(selected === agent.id ? null : agent.id)} aria-label="Agent details"><MoreVertical className="size-5"/></button></td></tr>)} </tbody></table>{!rows.length && <Empty>No agents match the current search.</Empty>}</div>{selected && <div className="border-t bg-[#f7f9f8] p-5 text-sm"><b>{agents.find((agent) => agent.id === selected)?.name}</b><p className="mt-1 text-[#71817c]">Retell configuration remains managed by Daiichi. Client users receive reporting access only.</p></div>}</div>;
}

export function RetellPhoneNumbersView({ phoneNumbers, agents }: { phoneNumbers: NonNullable<DashboardDataset["phoneNumbers"]>; agents: DashboardDataset["agents"] }) {
  const [search, setSearch] = useState(""); const [selected, setSelected] = useState<string | null>(null);
  const rows = phoneNumbers.filter((number) => `${number.prettyNumber} ${number.nickname}`.toLowerCase().includes(search.toLowerCase()));
  const chosen = rows.find((number) => number.number === selected);
  return <div className="glass min-h-[540px] overflow-hidden rounded-2xl md:grid md:grid-cols-[330px_1fr]"><aside className="border-r p-5"><div className="flex items-center justify-between"><h2 className="flex items-center gap-2 font-semibold"><Phone className="size-4"/>Phone Numbers</h2></div><label className="relative mt-5 block"><Search className="absolute left-3 top-1/2 size-4 -translate-y-1/2 text-[#84928d]"/><input value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Search phone numbers" className={`${control} w-full pl-10`}/></label><div className="mt-4 space-y-2">{rows.map((number) => <button key={number.number} onClick={() => setSelected(number.number)} className="w-full rounded-xl border bg-white p-4 text-left hover:border-[#1f7659]"><p className="font-semibold">{number.prettyNumber}</p><p className="text-xs text-[#71817c]">{number.nickname}</p></button>)}</div></aside><section className="grid place-items-center p-8">{chosen ? <div className="w-full max-w-2xl"><p className="text-xs font-bold uppercase tracking-wider text-[#1f7659]">{chosen.type}</p><h3 className="mt-2 text-3xl font-semibold">{chosen.prettyNumber}</h3><p className="mt-2 text-[#71817c]">{chosen.nickname}</p><div className="mt-6 grid gap-4 sm:grid-cols-2"><Binding title="Inbound agents" ids={chosen.inboundAgentIds} agents={agents}/><Binding title="Outbound agents" ids={chosen.outboundAgentIds} agents={agents}/></div></div> : <Empty>{rows.length ? "Select a phone number to view its Retell bindings." : "You don't have any phone numbers."}</Empty>}</section></div>;
}

function Binding({ title, ids, agents }: { title: string; ids: string[]; agents: DashboardDataset["agents"] }) { return <div className="rounded-2xl bg-[#f3f6f4] p-5"><p className="text-sm font-semibold">{title}</p><div className="mt-3 space-y-2">{ids.map((id) => <p key={id} className="text-sm">{agents.find((agent) => agent.providerId === id)?.name ?? "Agent outside current access"}</p>)}{!ids.length && <p className="text-sm text-[#84928d]">No binding</p>}</div></div>; }

export function LegacySessionHistoryView({ kind, calls, chats }: { kind: "call" | "chat"; calls: DashboardDataset["calls"]; chats: DashboardDataset["chats"] }) {
  const [search, setSearch] = useState(""); const [status, setStatus] = useState("all"); const [columnsOpen, setColumnsOpen] = useState(false);
  const [visible, setVisible] = useState<Record<string, boolean>>({ duration: true, channel: true, cost: true, session: true, reason: true, status: true, sentiment: true });
  const sessions = kind === "call" ? calls.map((call) => ({ id: call.sessionId ?? `${call.agent}-${call.time}`, time: call.time, agent: call.agent, duration: call.duration, channel: call.channel ?? "phone_call", cost: call.cost ?? "—", reason: call.endReason ?? call.outcome, status: call.status ?? "ended", sentiment: call.sentiment ?? "Neutral" })) : chats.map((chat) => ({ id: chat.sessionId ?? chat.id, time: chat.time, agent: chat.agent, duration: `${chat.messages} messages`, channel: "api_chat", cost: chat.cost ?? "—", reason: chat.outcome, status: chat.status, sentiment: chat.sentiment ?? "Neutral" }));
  const rows = sessions.filter((row) => (status === "all" || row.status === status) && `${row.id} ${row.agent} ${row.reason}`.toLowerCase().includes(search.toLowerCase()));
  const exportRows = () => downloadCsv(`${kind}-history.csv`, rows);
  return <div className="glass min-h-[520px] overflow-hidden rounded-2xl"><div className="flex flex-wrap items-center gap-3 p-5"><h2 className="mr-auto font-semibold">{kind === "call" ? "Call" : "Chat"} History</h2><label className="relative"><Search className="absolute left-3 top-1/2 size-4 -translate-y-1/2 text-[#84928d]"/><input value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Search sessions" className={`${control} pl-10`}/></label><select value={status} onChange={(e) => setStatus(e.target.value)} className={control}><option value="all">All statuses</option><option value="ended">Ended</option><option value="ongoing">Ongoing</option><option value="error">Error</option></select><div className="relative"><button onClick={() => setColumnsOpen(!columnsOpen)} className={`${control} flex items-center gap-2`}><Settings2 className="size-4"/>Columns</button>{columnsOpen && <div className="absolute right-0 top-12 z-20 w-48 rounded-xl border bg-white p-3 shadow-xl">{Object.keys(visible).map((column) => <label key={column} className="flex gap-2 p-2 text-sm capitalize"><input type="checkbox" checked={visible[column]} onChange={() => setVisible((current) => ({ ...current, [column]: !current[column] }))}/>{column}</label>)}</div>}</div><button onClick={exportRows} className={`${control} flex items-center gap-2 bg-[#253246] text-white`}><Download className="size-4"/>Export</button></div><div className="overflow-x-auto"><table className="w-full min-w-[1050px] text-left"><thead><tr className="bg-[#f1f3f5] text-xs text-[#596a7a]"><th className="p-4">Time</th><th className="p-4">Agent</th>{visible.duration&&<th className="p-4">Duration</th>}{visible.channel&&<th className="p-4">Channel Type</th>}{visible.cost&&<th className="p-4">Cost</th>}{visible.session&&<th className="p-4">Session ID</th>}{visible.reason&&<th className="p-4">End Reason</th>}{visible.status&&<th className="p-4">Session Status</th>}{visible.sentiment&&<th className="p-4">User Sentiment</th>}</tr></thead><tbody>{rows.map((row) => <tr key={row.id} className="border-b text-sm"><td className="p-4">{row.time}</td><td className="p-4">{row.agent}</td>{visible.duration&&<td className="p-4">{row.duration}</td>}{visible.channel&&<td className="p-4">{row.channel}</td>}{visible.cost&&<td className="p-4">{row.cost}</td>}{visible.session&&<td className="max-w-52 truncate p-4" title={row.id}>{row.id}</td>}{visible.reason&&<td className="p-4">{row.reason}</td>}{visible.status&&<td className="p-4 capitalize">{row.status}</td>}{visible.sentiment&&<td className="p-4">{row.sentiment}</td>}</tr>)}</tbody></table>{!rows.length&&<Empty>No sessions match the current filters.</Empty>}</div></div>;
}

export function LegacyRetellContactsView({ calls }: { calls: DashboardDataset["calls"] }) {
  const [search, setSearch] = useState(""); const [agent, setAgent] = useState("all");
  const contacts = useMemo(() => Array.from(new Map(calls.map((call) => [call.number, call])).values()), [calls]);
  const rows = contacts.filter((contact) => (agent === "all" || contact.agent === agent) && `${contact.contact} ${contact.number}`.toLowerCase().includes(search.toLowerCase()));
  const agents = Array.from(new Set(calls.map((call) => call.agent)));
  return <div className="glass min-h-[520px] overflow-hidden rounded-2xl"><div className="flex flex-wrap items-center gap-3 p-5"><h2 className="mr-auto font-semibold">Contacts</h2><select value={agent} onChange={(e) => setAgent(e.target.value)} className={control}><option value="all">All agents</option>{agents.map((name) => <option key={name}>{name}</option>)}</select><label className="relative"><Search className="absolute left-3 top-1/2 size-4 -translate-y-1/2 text-[#84928d]"/><input value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Search" className={`${control} pl-10`}/></label><button onClick={() => downloadCsv("contacts.csv", rows)} className={`${control} flex items-center gap-2 bg-[#253246] text-white`}><Download className="size-4"/>Export</button></div><div className="overflow-x-auto"><table className="w-full min-w-[900px] text-left"><thead><tr className="bg-[#f1f3f5] text-xs text-[#596a7a]"><th className="p-4">Phone Number</th><th className="p-4">Contact Name</th><th className="p-4">Related Agent</th><th className="p-4">Latest Conversation</th><th className="p-4">Do Not Call</th><th className="p-4">External ID</th></tr></thead><tbody>{rows.map((contact) => <tr key={contact.number} className="border-b text-sm"><td className="p-4">{contact.number}</td><td className="p-4">{contact.contact}</td><td className="p-4">{contact.agent}</td><td className="p-4">{contact.time}</td><td className="p-4">Not recorded</td><td className="p-4 text-[#84928d]">—</td></tr>)}</tbody></table>{!rows.length&&<Empty>No authorized contacts match the filters.</Empty>}</div></div>;
}

type HistoryRow = { id: string; time: string; agent: string; duration: string; channel: string; reason: string; status: string; sentiment: string; from: string; to: string };

export function SessionHistoryView({ kind, calls, chats }: { kind: "call" | "chat"; calls: DashboardDataset["calls"]; chats: DashboardDataset["chats"] }) {
  const [filterOpen, rawSetFilterOpen] = useState(false); const [actionsOpen, rawSetActionsOpen] = useState(false); const [columnsOpen, rawSetColumnsOpen] = useState(false); const [filterTab, setFilterTab] = useState("Base");
  const setFilterOpen = (value: boolean) => { rawSetFilterOpen(value); if (value) { rawSetActionsOpen(false); rawSetColumnsOpen(false); } };
  const setActionsOpen = (value: boolean) => { rawSetActionsOpen(value); if (value) { rawSetFilterOpen(false); rawSetColumnsOpen(false); } };
  const setColumnsOpen = (value: boolean) => { rawSetColumnsOpen(value); if (value) { rawSetFilterOpen(false); rawSetActionsOpen(false); } };
  const [agent, setAgent] = useState("all"); const [status, setStatus] = useState("all"); const [sentiment, setSentiment] = useState("all"); const [sessionQuery, setSessionQuery] = useState("");
  const [visible, setVisible] = useState<Record<string, boolean>>({ duration: kind === "call", channel: kind === "call", session: true, reason: kind === "call", status: true, sentiment: true, from: kind === "chat", to: kind === "chat" });
  const sessions: HistoryRow[] = kind === "call" ? calls.map((call) => ({ id: call.sessionId ?? `${call.agent}-${call.time}`, time: call.time, agent: call.agent, duration: call.duration, channel: call.channel ?? "phone_call", reason: call.endReason ?? call.outcome, status: call.status ?? "ended", sentiment: call.sentiment ?? "Neutral", from: call.number, to: "—" })) : chats.map((chat) => ({ id: chat.sessionId ?? chat.id, time: chat.time, agent: chat.agent, duration: `${chat.messages} messages`, channel: "api_chat", reason: chat.outcome, status: chat.status, sentiment: chat.sentiment ?? "Neutral", from: "—", to: "—" }));
  const agents = Array.from(new Set(sessions.map((row) => row.agent))); const statuses = Array.from(new Set(sessions.map((row) => row.status))); const sentiments = Array.from(new Set(sessions.map((row) => row.sentiment)));
  const rows = sessions.filter((row) => (agent === "all" || row.agent === agent) && (status === "all" || row.status === status) && (sentiment === "all" || row.sentiment === sentiment) && `${row.id} ${row.reason}`.toLowerCase().includes(sessionQuery.toLowerCase()));
  const baseFilters = kind === "call" ? ["Agent", "Transfer Agent", "Call ID", "Batch Call ID", "Type", "Duration", "From", "To", "User Sentiment", "Disconnection Reason", "Call Status", "Call Successful"] : ["Agent", "Chat ID", "User Sentiment", "Disconnection Reason", "Chat Successful", "Chat Status"];
  const tabs = kind === "call" ? ["Base", "Post Call Analysis", "Metadata", "Dynamic Variables"] : ["Base", "Post Chat Analysis"];
  return <div className="glass min-h-[520px] overflow-hidden rounded-2xl"><div className="border-b p-4"><h2 className="flex items-center gap-2 font-semibold"><RefreshCw className="size-4 text-[#667487]"/>{kind === "call" ? "Call" : "Chat"} History</h2><div className="mt-4 flex flex-wrap items-center gap-3"><div className="relative"><button type="button" onClick={() => setFilterOpen(!filterOpen)} className={`${control} flex items-center gap-2`}><Filter className="size-4"/>Filter</button>{filterOpen && <div className="absolute left-0 top-12 z-30 w-[min(92vw,460px)] rounded-2xl border bg-white p-4 shadow-2xl"><div className="flex gap-5 overflow-x-auto border-b">{tabs.map((tab) => <button type="button" key={tab} onClick={() => setFilterTab(tab)} className={`whitespace-nowrap border-b-2 pb-3 text-sm ${filterTab === tab ? "border-[#253246] font-semibold" : "border-transparent text-[#697789]"}`}>{tab}</button>)}</div>{filterTab === "Base" ? <div className="mt-3 max-h-[420px] space-y-1 overflow-y-auto">{baseFilters.map((name) => <div key={name} className="rounded-xl px-2 py-2"><p className="flex items-center gap-3 text-sm font-medium"><CirclePlus className="size-4 text-[#697789]"/>{name}</p>{name === "Agent" && <select value={agent} onChange={(e) => setAgent(e.target.value)} className={`${control} mt-2 w-full`}><option value="all">All agents</option>{agents.map((item) => <option key={item}>{item}</option>)}</select>}{name.endsWith("Status") && <select value={status} onChange={(e) => setStatus(e.target.value)} className={`${control} mt-2 w-full`}><option value="all">All statuses</option>{statuses.map((item) => <option key={item}>{item}</option>)}</select>}{name === `${kind === "call" ? "Call" : "Chat"} ID` && <input value={sessionQuery} onChange={(e) => setSessionQuery(e.target.value)} placeholder={`Search ${name.toLowerCase()}`} className={`${control} mt-2 w-full`}/>} {name === "User Sentiment" && <select value={sentiment} onChange={(e) => setSentiment(e.target.value)} className={`${control} mt-2 w-full`}><option value="all">All sentiments</option>{sentiments.map((item) => <option key={item}>{item}</option>)}</select>}</div>)}</div> : <Empty>No synchronized custom fields are available.</Empty>}<div className="mt-3 flex justify-end border-t pt-3"><button type="button" onClick={() => setFilterOpen(false)} className="rounded-lg bg-[#253246] px-4 py-2 text-sm font-semibold text-white">Apply filters</button></div></div>}</div><div className="ml-auto relative"><button type="button" aria-label="Manage columns" onClick={() => setColumnsOpen(!columnsOpen)} className={`${control} grid w-11 place-items-center px-0`}><Settings2 className="size-4"/></button>{columnsOpen && <div className="absolute right-0 top-12 z-20 w-52 rounded-xl border bg-white p-3 shadow-xl">{Object.keys(visible).filter((column) => kind === "chat" || !["from", "to"].includes(column)).map((column) => <label key={column} className="flex gap-2 p-2 text-sm capitalize"><input type="checkbox" checked={visible[column]} onChange={() => setVisible((current) => ({ ...current, [column]: !current[column] }))}/>{column === "session" ? "Session ID" : column}</label>)}</div>}</div><div className="relative"><button type="button" onClick={() => setActionsOpen(!actionsOpen)} className="flex h-11 items-center gap-2 rounded-xl bg-[#2d394b] px-4 text-sm font-semibold text-white">Actions<ChevronDown className="size-4"/></button>{actionsOpen && <div className="absolute right-0 top-12 z-30 w-56 rounded-xl border bg-white p-2 text-[#253246] shadow-xl"><button type="button" onClick={() => { downloadCsv(`${kind}-history.csv`, rows); setActionsOpen(false); }} className="w-full rounded-lg px-3 py-2 text-left text-sm hover:bg-[#f1f3f5]">Export current view</button></div>}</div></div></div><div className="overflow-x-auto"><table className="w-full min-w-[1050px] text-left"><thead><tr className="bg-[#f1f3f5] text-xs text-[#596a7a]"><th className="p-4">Time</th><th className="p-4">Agent</th>{visible.duration&&<th className="p-4">Duration</th>}{visible.channel&&<th className="p-4">Channel Type</th>}{visible.session&&<th className="p-4">Session ID</th>}{visible.reason&&<th className="p-4">End Reason</th>}{visible.status&&<th className="p-4">Session Status</th>}{visible.sentiment&&<th className="p-4">User Sentiment</th>}{visible.from&&<th className="p-4">From</th>}{visible.to&&<th className="p-4">To</th>}</tr></thead><tbody>{rows.map((row) => <tr key={row.id} className="border-b text-sm"><td className="p-4">{row.time}</td><td className="p-4">{row.agent}</td>{visible.duration&&<td className="p-4">{row.duration}</td>}{visible.channel&&<td className="p-4">{row.channel}</td>}{visible.session&&<td className="max-w-52 truncate p-4" title={row.id}>{row.id}</td>}{visible.reason&&<td className="p-4">{row.reason}</td>}{visible.status&&<td className="p-4 capitalize">{row.status}</td>}{visible.sentiment&&<td className="p-4">{row.sentiment}</td>}{visible.from&&<td className="p-4">{row.from}</td>}{visible.to&&<td className="p-4">{row.to}</td>}</tr>)}</tbody></table>{!rows.length&&<Empty>No sessions match the current filters.</Empty>}</div><div className="flex items-center justify-between border-t p-4 text-sm text-[#71817c]"><span>Page 1 of 1 • Total Sessions: {rows.length}</span><span className="rounded-lg border px-3 py-2">50 / page</span></div></div>;
}

function ActionItem({ icon: Icon, label, onClick }: { icon: typeof Settings2; label: string; onClick?: () => void; disabled?: boolean }) { const [modal, setModal] = useState<"create" | "backfill" | "fields" | null>(null); const click = () => { if (label === "Add contact") setModal("create"); else if (label === "Backfill from Post-Call Data") setModal("backfill"); else if (label === "Manage contact fields") setModal("fields"); else (onClick ?? (() => window.dispatchEvent(new CustomEvent("contact-action", { detail: label }))))(); }; return <><button type="button" onClick={click} className="flex w-full items-center gap-3 rounded-lg px-3 py-2 text-left text-sm hover:bg-[#f1f3f5]"><Icon className="size-4"/>{label}</button>{modal === "create" && <AddContactModal close={() => setModal(null)}/>} {modal === "backfill" && <ContactBackfillModal close={() => setModal(null)}/>} {modal === "fields" && <ContactFieldsModal close={() => setModal(null)}/>}</>; }

function ContactModal({ title, close, children, footer }: { title: string; close: () => void; children: React.ReactNode; footer: React.ReactNode }) { return <div onMouseDown={(event) => { if (event.target === event.currentTarget) close(); }} className="fixed inset-0 z-[300] grid place-items-center bg-[#1c252e66] p-4" role="dialog" aria-modal="true" aria-label={title}><section onMouseDown={(event) => event.stopPropagation()} className="flex max-h-[92vh] w-full max-w-3xl flex-col overflow-hidden rounded-2xl border border-[#cdd5e1] bg-white text-[#253246] shadow-2xl"><header className="flex items-center justify-between border-b px-5 py-4"><h3 className="text-xl font-semibold">{title}</h3><button type="button" onClick={close} aria-label="Close" className="rounded-lg p-2 text-[#9aa5b2] transition hover:bg-[#f1f3f5] hover:text-[#253246]"><X className="size-5"/></button></header><div className="min-h-0 flex-1 overflow-y-auto p-5">{children}</div><footer className="flex justify-end gap-3 border-t px-5 py-5">{footer}</footer></section></div>; }

type ContactFieldItem = { name: string; label: string; type: string; description?: string; mapping?: string; mappingMode?: "overwrite" | "fill_if_empty" | "merge"; updatedAt?: number; builtIn?: boolean };
type PostCallField = { name: string; type: string; description?: string; agents: string[] };
function ContactFieldsModal({ close }: { close: () => void }) {
  const [fields, setFields] = useState<ContactFieldItem[]>([]); const [, setAnalysisFields] = useState<PostCallField[]>([]); const [loading, setLoading] = useState(true); const [editing, setEditing] = useState<ContactFieldItem | "new" | null>(null); const [backfillOpen, setBackfillOpen] = useState(false); const [error, setError] = useState("");
  const load = async () => { setLoading(true); try { const response = await fetch("/api/admin/contacts", { cache: "no-store" }); const result = await response.json() as { error?: string; fields?: ContactFieldItem[]; analysisFields?: PostCallField[] }; if (!response.ok) throw new Error(result.error ?? "Unable to load contact fields"); setFields(result.fields ?? []); setAnalysisFields(result.analysisFields ?? []); } catch (reason) { setError(reason instanceof Error ? reason.message : "Unable to load contact fields"); } finally { setLoading(false); } };
  // Loading the external Retell configuration initializes this management view.
  // eslint-disable-next-line react-hooks/set-state-in-effect
  useEffect(() => { void load(); }, []);
  const saved = () => { setEditing(null); void load(); };
  return <div className="fixed inset-0 z-[310] overflow-y-auto bg-white text-[#253246]" role="dialog" aria-modal="true" aria-label="Contact Fields"><div className="min-h-screen p-4 md:p-7"><header className="flex flex-wrap items-center gap-3"><button type="button" onClick={close} aria-label="Back to contacts" className="grid size-11 place-items-center rounded-xl border"><ChevronLeft className="size-5"/></button><h2 className="text-2xl font-semibold">Contact Fields</h2><div className="flex w-full flex-wrap gap-3 sm:ml-auto sm:w-auto"><button onClick={() => setBackfillOpen(true)} className="flex h-11 flex-1 items-center justify-center gap-2 whitespace-nowrap rounded-xl border px-4 font-semibold sm:flex-none"><Database className="size-4"/>Backfill Post Call Extraction</button><button onClick={() => setEditing("new")} className="flex h-11 flex-1 items-center justify-center gap-2 whitespace-nowrap rounded-xl border px-4 font-semibold sm:flex-none"><Plus className="size-4"/>Add Contact Field</button></div></header><div className="mt-7 overflow-x-auto"><div className="min-w-[850px]"><div className="grid grid-cols-[1.1fr_1.1fr_1.1fr_1fr_44px] gap-3 rounded-xl bg-[#f0f3f7] px-5 py-3 text-sm text-[#596a7a]"><span>Contact field</span><span>CRM field sync</span><span>Post-call data mapping</span><span>Last updated</span><span/></div>{loading ? <p className="p-10 text-center">Loading Retell contact fields…</p> : fields.map((field) => { const FieldIcon = field.type === "boolean" ? Eye : Type; return <div key={field.name} className="grid grid-cols-[1.1fr_1.1fr_1.1fr_1fr_44px] items-center gap-3 border-b px-5 py-5"><span className="flex items-center gap-4"><FieldIcon className="size-5 text-[#697789]"/>{field.label}</span><span className="text-[#b3bdca]">—</span><span className="truncate text-[#b3bdca]" title={field.mapping}>{field.mapping ?? "—"}</span><span>{field.updatedAt ? new Date(field.updatedAt).toLocaleString() : "—"}</span>{field.name !== "phone_number" ? <button onClick={() => setEditing(field)} aria-label={`Edit ${field.label}`} className="grid size-9 place-items-center rounded-lg hover:bg-[#f1f3f5]"><Pencil className="size-4"/></button> : <span/>}</div>; })}</div></div>{error && <p className="mt-4 text-rose-700">{error}</p>}</div>{editing && <ContactFieldEditor field={editing === "new" ? undefined : editing} close={() => setEditing(null)} saved={saved}/>} {backfillOpen && <ContactBackfillModal close={() => setBackfillOpen(false)}/>}</div>;
}

function ContactFieldEditor({ field, close, saved }: { field?: ContactFieldItem; close: () => void; saved: () => void }) {
  const isNew = !field; const [name, setName] = useState(field?.name ?? ""); const [label, setLabel] = useState(field?.label ?? ""); const [type, setType] = useState(field?.type ?? "string"); const [description, setDescription] = useState(field?.description ?? ""); const [mapPostCall, setMapPostCall] = useState(Boolean(field?.mapping)); const [analysisDataName, setAnalysisDataName] = useState(field?.mapping ?? ""); const [updateMode, setUpdateMode] = useState<"overwrite" | "fill_if_empty" | "merge">(field?.mappingMode ?? "fill_if_empty"); const [analysisFields, setAnalysisFields] = useState<PostCallField[]>([]); const [busy, setBusy] = useState(false); const [error, setError] = useState("");
  useEffect(() => { void fetch("/api/admin/contacts", { cache: "no-store" }).then((response) => response.json()).then((result: { analysisFields?: PostCallField[] }) => setAnalysisFields(result.analysisFields ?? [])).catch(() => setAnalysisFields([])); }, []);
  const changeFieldName = (value: string) => { setLabel(value); setName(value.trim().toLowerCase().replace(/[^a-z0-9]+/g, "_").replace(/^_+|_+$/g, "")); };
  const changeType = (value: string) => { setType(value); if (value !== "string" && updateMode === "merge") setUpdateMode("fill_if_empty"); };
  const submit = async (action: "save" | "delete") => { if (action === "delete" && !window.confirm(`Delete ${field?.label}? This also removes its mapping.`)) return; setBusy(true); setError(""); try { const body = action === "delete" ? { action: "delete_field", name: field?.name } : { action: isNew ? "add_field" : "update_field", ...(isNew ? { name } : { originalName: field!.name }), label, fieldType: type, description, mapPostCall, analysisDataName, updateMode }; const response = await fetch("/api/admin/contacts", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify(body) }); const result = await response.json() as { error?: string }; if (!response.ok) throw new Error(result.error ?? "Unable to save contact field"); saved(); } catch (reason) { setError(reason instanceof Error ? reason.message : "Unable to save contact field"); } finally { setBusy(false); } };
  const invalidMapping = mapPostCall && !analysisDataName;
  const enhancedFooter = <><div className="mr-auto">{field && !field.builtIn && <button type="button" disabled={busy} onClick={() => void submit("delete")} className="h-11 rounded-xl border border-rose-200 bg-rose-50 px-5 font-semibold text-rose-700 transition hover:bg-rose-100">Delete</button>}</div><button type="button" onClick={close} className="h-11 rounded-xl border px-5 font-semibold transition hover:bg-[#f3f5f7]">Cancel</button><button type="button" disabled={busy || !label.trim() || invalidMapping || (isNew && !/^[a-z][a-z0-9_]*$/.test(name))} onClick={() => void submit("save")} className="h-11 rounded-xl bg-[#2d394b] px-5 font-semibold text-white transition hover:bg-[#1f2a3a] disabled:cursor-not-allowed disabled:opacity-40">{busy ? "Saving…" : isNew ? "Create" : "Save"}</button></>;
  return <ContactModal title={isNew ? "Add contact field" : "Edit contact field"} close={close} footer={enhancedFooter}>
    <div className="grid gap-3 sm:grid-cols-[165px_1fr]">
      <label className="font-medium">Type<select value={type} disabled={Boolean(field?.builtIn)} onChange={(event) => changeType(event.target.value)} className={`${control} mt-2 w-full disabled:bg-[#f5f7f9]`}><option value="string">Text</option><option value="number">Number</option><option value="boolean">Boolean</option><option value="date">Date</option><option value="datetime">Date and time</option></select></label>
      <label className="font-medium">Field name<input autoFocus={isNew} value={label} onChange={(event) => isNew ? changeFieldName(event.target.value) : setLabel(event.target.value)} disabled={Boolean(field?.builtIn)} placeholder="e.g. Customer need" className={`${control} mt-2 w-full disabled:bg-[#f5f7f9]`}/>{isNew && <span className="mt-2 block text-sm text-[#71817c]">Once created, the field type can&apos;t be changed.</span>}</label>
    </div>
    <label className="mt-6 block font-medium">Description<textarea value={description} onChange={(event) => setDescription(event.target.value)} placeholder="What this field captures" className="mt-2 min-h-20 w-full rounded-xl border border-[#d9dee7] p-3 outline-none transition focus:border-[#1f7659] focus:ring-4 focus:ring-[#1f765915]"/></label>
    <div className="mt-6 flex items-center justify-between gap-4"><div><p className="font-semibold">Map with Post-Call Data</p><p className="text-sm text-[#71817c]">Auto-update this field from live Retell analysis data.</p></div><button type="button" role="switch" aria-checked={mapPostCall} aria-label="Map with Post-Call Data" onClick={() => setMapPostCall((current) => !current)} className={`relative h-6 w-11 shrink-0 rounded-full transition-colors ${mapPostCall ? "bg-[#2d394b]" : "bg-[#e2e7ef]"}`}><span className={`absolute left-1 top-1 size-4 rounded-full bg-white shadow-sm transition-transform ${mapPostCall ? "translate-x-5" : ""}`}/></button></div>
    {mapPostCall && <div className="mt-4 rounded-2xl bg-[#f7f8fa] p-4"><label className="block"><span className="sr-only">Post-call data attribute</span><select value={analysisDataName} onChange={(event) => setAnalysisDataName(event.target.value)} className={`${control} w-full`}><option value="">Select Post-Call Data attribute</option>{analysisFields.map((item) => <option key={item.name} value={item.name}>{item.name} · {item.type}</option>)}</select></label>{analysisFields.length === 0 && <p className="mt-2 text-sm text-amber-700">No post-call attributes are configured on the connected Retell voice agents.</p>}<fieldset className="mt-6 space-y-3"><legend className="mb-3 font-semibold">Fill in logic</legend>{([{ value: "overwrite", label: "Overwrite with latest value" }, { value: "fill_if_empty", label: "Fill only if empty" }, { value: "merge", label: "Accumulate and summarize (Agentic)" }] as const).map((option) => <label key={option.value} className={`flex cursor-pointer items-center gap-3 rounded-lg px-2 py-1.5 transition hover:bg-white ${option.value === "merge" && type !== "string" ? "cursor-not-allowed opacity-45" : ""}`}><input type="radio" name="contact-update-mode" value={option.value} checked={updateMode === option.value} disabled={option.value === "merge" && type !== "string"} onChange={() => setUpdateMode(option.value)} className="size-5 accent-[#2d394b]"/><span>{option.label}</span></label>)}</fieldset></div>}
    {error && <p className="mt-4 rounded-xl bg-rose-50 p-3 text-rose-700">{error}</p>}
  </ContactModal>;
}

function AddContactModal({ close }: { close: () => void }) {
  const [phoneNumber, setPhoneNumber] = useState(""); const [firstName, setFirstName] = useState(""); const [lastName, setLastName] = useState(""); const [doNotCall, setDoNotCall] = useState("false"); const [call, setCall] = useState(false); const [busy, setBusy] = useState(false); const [error, setError] = useState("");
  const create = async () => { setBusy(true); setError(""); try { const response = await fetch("/api/admin/contacts", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ action: "create", phoneNumber, firstName, lastName, doNotCall: doNotCall === "true", call }) }); const result = await response.json() as { error?: string }; if (!response.ok) throw new Error(result.error ?? "Unable to create contact"); close(); } catch (reason) { setError(reason instanceof Error ? reason.message : "Unable to create contact"); } finally { setBusy(false); } };
  const fieldClass = `${control} w-full`;
  return <ContactModal title="Add Contact" close={close} footer={<><button type="button" onClick={close} className="h-11 rounded-xl border px-5 font-semibold">Cancel</button><button type="button" onClick={() => void create()} disabled={busy || !/^\+[1-9]\d{7,14}$/.test(phoneNumber)} className="h-11 rounded-xl bg-[#2d394b] px-5 font-semibold text-white disabled:opacity-40">{busy ? "Creating…" : "Create"}</button></>}><div className="grid items-center gap-4 sm:grid-cols-[240px_1fr]"><label className="font-semibold">Phone number <span className="text-rose-600">*</span></label><input autoFocus value={phoneNumber} onChange={(event) => setPhoneNumber(event.target.value)} placeholder="+14155552671" className={fieldClass}/><label className="font-semibold">First name</label><input value={firstName} onChange={(event) => setFirstName(event.target.value)} placeholder="Ada" className={fieldClass}/><label className="font-semibold">Last name</label><input value={lastName} onChange={(event) => setLastName(event.target.value)} placeholder="Lovelace" className={fieldClass}/><label className="font-semibold">Do not call</label><select value={doNotCall} onChange={(event) => setDoNotCall(event.target.value)} className={fieldClass}><option value="false">False</option><option value="true">True</option></select><div className="sm:col-span-2 mt-2 border-t pt-5"><p className="mb-5 text-sm font-semibold text-[#8a98aa]">Custom fields</p><div className="grid items-center sm:grid-cols-[240px_1fr]"><span className="font-semibold">Call</span><button type="button" role="switch" aria-checked={call} aria-label="Call custom field" onClick={() => setCall((current) => !current)} className={`relative h-6 w-11 rounded-full transition ${call ? "bg-[#3977f6]" : "bg-[#e4e8f2]"}`}><span className={`absolute top-1 size-4 rounded-full bg-white shadow-sm transition-transform ${call ? "left-1 translate-x-5" : "left-1"}`}/></button></div></div></div>{error && <p className="mt-4 rounded-xl bg-rose-50 p-3 text-sm text-rose-700">{error}</p>}</ContactModal>;
}

type ContactBackfillRow = { id: number; type: "time" | "agent" | "batch"; value: string };
function ContactBackfillModal({ close }: { close: () => void }) { const [fields, setFields] = useState(""); const [rows, setRows] = useState<ContactBackfillRow[]>([{ id: 1, type: "time", value: "" }]); const [busy, setBusy] = useState(false); const [error, setError] = useState(""); const update = (id: number, patch: Partial<ContactBackfillRow>) => setRows((current) => current.map((row) => row.id === id ? { ...row, ...patch } : row)); const add = () => setRows((current) => [...current, { id: Math.max(0, ...current.map((row) => row.id)) + 1, type: "agent", value: "" }]); const save = async () => { const attributes = fields.split(",").map((field) => field.trim()).filter(Boolean); if (!attributes.length) return; setBusy(true); setError(""); try { const response = await fetch("/api/admin/contacts", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ action: "backfill", attributes, filters: rows.filter((row) => row.value) }) }); const result = await response.json() as { error?: string }; if (!response.ok) throw new Error(result.error ?? "Unable to start backfill"); close(); } catch (reason) { setError(reason instanceof Error ? reason.message : "Unable to start backfill"); } finally { setBusy(false); } }; return <ContactModal title="Backfill Post Call Extraction" close={close} footer={<><button type="button" onClick={close} className="h-11 rounded-xl border px-5 font-semibold">Cancel</button><button type="button" onClick={() => void save()} disabled={busy || !fields.trim()} className="h-11 rounded-xl bg-[#2d394b] px-5 font-semibold text-white disabled:opacity-40">{busy ? "Saving…" : "Save"}</button></>}><label className="text-sm font-semibold text-[#596a7a]">New Fields<input value={fields} onChange={(event) => setFields(event.target.value)} placeholder="Enter Retell contact field names, separated by commas" className={`${control} mt-2 w-full`}/></label><p className="mb-3 mt-7 text-sm font-semibold text-[#596a7a]">Filter on calls</p><div className="rounded-xl border bg-[#fafbfc] p-4"><div className="space-y-3">{rows.map((row) => <div key={row.id} className="grid gap-3 sm:grid-cols-[155px_1fr_auto]"><label className="text-xs text-[#71817c]">Type<select value={row.type} onChange={(event) => update(row.id, { type: event.target.value as ContactBackfillRow["type"], value: "" })} className={`${control} mt-2 w-full`}><option value="time">Call time</option><option value="agent">Agent</option><option value="batch">Batch Call ID</option></select></label><label className="text-xs text-[#71817c]">Value<div className="relative mt-2"><input type={row.type === "time" ? "date" : "text"} value={row.value} onChange={(event) => update(row.id, { value: event.target.value })} placeholder={row.type === "time" ? "Select date" : "Enter value"} className={`${control} w-full pl-10`}/>{row.type === "time" && <CalendarDays className="absolute left-3 top-1/2 size-4 -translate-y-1/2 text-[#697789]"/>}</div></label><button type="button" onClick={() => setRows((current) => current.filter((item) => item.id !== row.id))} aria-label="Delete filter" className="mt-6 grid size-11 place-items-center text-[#71817c] hover:text-rose-600"><Trash2 className="size-4"/></button></div>)}</div><button type="button" onClick={add} className="mt-4 flex h-11 items-center gap-2 rounded-xl border bg-white px-4 text-sm font-semibold"><Plus className="size-4"/>Add</button></div>{error && <p className="mt-4 rounded-xl bg-rose-50 p-3 text-sm text-rose-700">{error}</p>}</ContactModal>; }

function ManagedRetellContactsView({ calls }: { calls: DashboardDataset["calls"] }) {
  type ContactFilter = "phone" | "contact" | "external" | "dnc" | "latest";
  const filterLabels: Record<ContactFilter, string> = { phone: "Phone Number", contact: "Contact ID", external: "External ID", dnc: "Do Not Call", latest: "Latest Conversation" };
  const [search, setSearch] = useState(""); const [filterOpen, rawSetFilterOpen] = useState(false); const [actionsOpen, rawSetActionsOpen] = useState(false); const [activeFilters, setActiveFilters] = useState<ContactFilter[]>([]); const [filterValues, setFilterValues] = useState<Record<ContactFilter, string>>({ phone: "", contact: "", external: "", dnc: "all", latest: "" }); const [, setContactMessage] = useState(""); const [, setContactBusy] = useState(false);
  const setFilterOpen = (value: boolean) => { rawSetFilterOpen(value); if (value) rawSetActionsOpen(false); };
  const setActionsOpen = (value: boolean) => { rawSetActionsOpen(value); if (value) rawSetFilterOpen(false); };
  const contacts = useMemo(() => Array.from(new Map(calls.map((call) => [call.contact, call])).values()).map((contact) => ({ ...contact, contactId: "", externalId: "", doNotCall: "not_recorded", conversations: calls.filter((call) => call.contact === contact.contact).length })), [calls]);
  const updateFilter = (key: ContactFilter, value: string) => setFilterValues((current) => ({ ...current, [key]: value }));
  const removeFilter = (key: ContactFilter) => { setActiveFilters((current) => current.filter((item) => item !== key)); updateFilter(key, key === "dnc" ? "all" : ""); };
  const clearFilters = () => { setActiveFilters([]); setFilterValues({ phone: "", contact: "", external: "", dnc: "all", latest: "" }); setFilterOpen(false); };
  async function contactAction(action: "sync" | "backfill" | "create") {
    setActionsOpen(false); setContactMessage(""); setContactBusy(true);
    try {
      let body: Record<string, unknown> = { action };
      if (action === "create") { const phoneNumber = window.prompt("Enter the contact phone number in international format (for example +923001234567):")?.trim(); if (!phoneNumber) return; const firstName = window.prompt("Enter the first name (optional):")?.trim(); const lastName = window.prompt("Enter the last name (optional):")?.trim(); body = { action, phoneNumber, firstName, lastName }; }
      if (action === "backfill") { const attributes = window.prompt("Enter the Retell contact field names to backfill, separated by commas:")?.split(",").map((value) => value.trim()).filter(Boolean); if (!attributes?.length) return; body = { action, attributes }; }
      const endpoint = action === "sync" ? "/api/admin/agents/import" : "/api/admin/contacts";
      const response = await fetch(endpoint, { method: "POST", headers: { "content-type": "application/json" }, body: action === "sync" ? undefined : JSON.stringify(body) });
      const result = await response.json() as { error?: string; message?: string };
      if (!response.ok) throw new Error(result.error ?? "Contact action failed");
      const message = result.message ?? (action === "sync" ? "Retell data synchronized." : action === "backfill" ? "Contact backfill queued in Retell." : "Contact added to Retell."); setContactMessage(message); window.alert(message);
    } catch (error) { const message = error instanceof Error ? error.message : "Contact action failed"; setContactMessage(message); window.alert(message); }
    finally { setContactBusy(false); }
  }
  useEffect(() => {
    const handle = (event: Event) => {
      const label = (event as CustomEvent<string>).detail;
      if (label === "Run full sync") void contactAction("sync");
      else if (label === "Backfill from Post-Call Data") void contactAction("backfill");
      else if (label === "Add contact") void contactAction("create");
      else window.alert(label === "Manage CRM sync" ? "CRM synchronization is managed by the connected Retell workspace." : "All authorized Retell contact fields are displayed in the table.");
    };
    window.addEventListener("contact-action", handle);
    return () => window.removeEventListener("contact-action", handle);
  });
  const rows = contacts.filter((contact) => `${contact.contact} ${contact.number} ${contact.time}`.toLowerCase().includes(search.toLowerCase()) && activeFilters.every((field) => { const value = filterValues[field].trim().toLowerCase(); if (!value || value === "all") return true; if (field === "phone") return contact.number.toLowerCase().includes(value); if (field === "contact") return contact.contactId.toLowerCase().includes(value); if (field === "external") return contact.externalId.toLowerCase().includes(value); if (field === "dnc") return contact.doNotCall === value; return Boolean(contact.startedAt && contact.startedAt.slice(0, 10) >= value); }));
  return <div className="glass min-h-[520px] overflow-hidden rounded-2xl"><div className="p-5"><div className="flex items-center"><h2 className="font-semibold">Contacts</h2><span className="ml-auto text-sm"><ContactRound className="mr-2 inline size-4"/>Feedback</span></div><div className="mt-8 flex flex-wrap items-center gap-3"><div className="relative"><button type="button" onClick={() => setFilterOpen(!filterOpen)} className={`${control} flex items-center gap-2`}><Filter className="size-4"/>Filter{activeFilters.length > 0 && <span className="grid size-5 place-items-center rounded-full bg-[#253246] text-[10px] text-white">{activeFilters.length}</span>}</button>{filterOpen && <div className="absolute left-0 top-12 z-30 w-80 rounded-2xl border bg-white p-3 shadow-2xl">{(Object.entries(filterLabels) as Array<[ContactFilter,string]>).map(([value,label]) => <button type="button" key={value} disabled={activeFilters.includes(value)} onClick={() => setActiveFilters((current) => [...current, value])} className="flex w-full items-center gap-3 rounded-xl px-4 py-3 text-left text-sm hover:bg-[#f1f3f5] disabled:bg-[#f5f7f9] disabled:text-[#9aa5b2]"><CirclePlus className="size-4 text-[#697789]"/>{label}</button>)}{activeFilters.length > 0 && <button type="button" onClick={clearFilters} className="mt-2 w-full border-t px-4 py-3 text-left text-sm text-[#a34747]">Clear filters</button>}</div>}</div><label className="relative ml-auto"><Search className="absolute left-3 top-1/2 size-4 -translate-y-1/2 text-[#84928d]"/><input value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Search" className={`${control} w-72 pl-10`}/></label><button type="button" aria-label="Contact display settings" className={`${control} grid w-11 place-items-center px-0`}><Settings2 className="size-4"/></button><div className="relative"><button type="button" onClick={() => setActionsOpen(!actionsOpen)} className="flex h-11 items-center gap-2 rounded-xl bg-[#2d394b] px-4 text-sm font-semibold text-white">Actions<ChevronDown className="size-4"/></button>{actionsOpen && <div className="absolute right-0 top-12 z-30 w-72 rounded-2xl border bg-white p-2 text-[#253246] shadow-2xl"><ActionItem icon={Settings2} label="Manage contact fields" disabled/><ActionItem icon={Database} label="Manage CRM sync" disabled/><ActionItem icon={RefreshCw} label="Run full sync" disabled/><ActionItem icon={Database} label="Backfill from Post-Call Data" disabled/><ActionItem icon={UserPlus} label="Add contact" disabled/><p className="px-3 py-2 text-[11px] text-[#84928d]">Contact changes are managed in Retell by Daiichi administrators.</p></div>}</div></div>{activeFilters.length > 0 && <div className="mt-4 grid gap-3 rounded-xl bg-[#f5f7f9] p-3 sm:grid-cols-2 xl:grid-cols-3">{activeFilters.map((field) => <label key={field} className="relative text-xs font-semibold text-[#596a7a]">{filterLabels[field]}{field === "dnc" ? <select value={filterValues[field]} onChange={(event) => updateFilter(field, event.target.value)} className={`${control} mt-2 w-full pr-10`}><option value="all">All</option><option value="true">Yes</option><option value="false">No</option><option value="not_recorded">Not recorded</option></select> : <input type={field === "latest" ? "date" : "text"} value={filterValues[field]} onChange={(event) => updateFilter(field, event.target.value)} placeholder={`Filter by ${filterLabels[field].toLowerCase()}`} className={`${control} mt-2 w-full pr-10`}/>}<button type="button" aria-label={`Remove ${filterLabels[field]} filter`} onClick={() => removeFilter(field)} className="absolute bottom-3 right-3 text-[#84928d] hover:text-rose-600">×</button></label>)}</div>}</div><div className="overflow-x-auto"><table className="w-full min-w-[1100px] text-left"><thead><tr className="bg-[#f1f3f5] text-xs text-[#596a7a]"><th className="p-4">Phone Number</th><th className="p-4">First Name</th><th className="p-4">Last Name</th><th className="p-4">Contact ID</th><th className="p-4">Related Conversations</th><th className="p-4">Latest Conversation</th><th className="p-4">Do Not Call</th><th className="p-4">External ID</th></tr></thead><tbody>{rows.map((contact) => { const parts = contact.contact.trim().split(/\s+/); return <tr key={contact.number} className="border-b text-sm"><td className="p-4">{contact.number}</td><td className="p-4">{parts[0] ?? "—"}</td><td className="p-4">{parts.slice(1).join(" ") || "—"}</td><td className="p-4 text-[#84928d]">{contact.contactId || "—"}</td><td className="p-4">{contact.conversations}</td><td className="p-4">{contact.time}</td><td className="p-4 capitalize">{contact.doNotCall.replace("_", " ")}</td><td className="p-4 text-[#84928d]">{contact.externalId || "—"}</td></tr>; })}</tbody></table>{!rows.length&&<Empty>No authorized contacts match the filters.</Empty>}</div></div>;
}

export function RetellContactsView({ calls, canManage, canExport }: { calls: DashboardDataset["calls"]; canManage: boolean; canExport: boolean }) {
  return canManage ? <ManagedRetellContactsView calls={calls}/> : <ReadOnlyContactsView calls={calls} canExport={canExport}/>;
}

function ReadOnlyContactsView({ calls, canExport }: { calls: DashboardDataset["calls"]; canExport: boolean }) {
  void canExport;
  const [search, setSearch] = useState("");
  const contacts = useMemo(() => Array.from(new Map(calls.map((call) => [call.contact, call])).values()).map((contact) => ({ ...contact, conversations: calls.filter((call) => call.contact === contact.contact).length })), [calls]);
  const rows = contacts.filter((contact) => `${contact.contact} ${contact.number} ${contact.time}`.toLowerCase().includes(search.toLowerCase()));
  return <div className="glass min-h-[520px] overflow-hidden rounded-2xl"><div className="flex flex-wrap items-center gap-3 border-b p-5"><div><h2 className="font-semibold">Contacts</h2><p className="mt-1 text-xs text-[#71817c]">Read-only contacts from your authorized agent calls.</p></div><label className="relative ml-auto"><Search className="absolute left-3 top-1/2 size-4 -translate-y-1/2 text-[#84928d]"/><input value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Search contacts" className={`${control} w-72 pl-10`}/></label></div><div className="overflow-x-auto"><table className="w-full min-w-[850px] text-left"><thead><tr className="bg-[#f1f3f5] text-xs text-[#596a7a]"><th className="p-4">Phone Number</th><th className="p-4">Contact</th><th className="p-4">Related Conversations</th><th className="p-4">Latest Conversation</th></tr></thead><tbody>{rows.map((contact) => <tr key={contact.number} className="border-b text-sm"><td className="p-4">{contact.number}</td><td className="p-4">{contact.contact}</td><td className="p-4">{contact.conversations}</td><td className="p-4">{contact.time}</td></tr>)}</tbody></table>{!rows.length && <Empty>No authorized contacts match this search.</Empty>}</div></div>;
}

export function RetellAnalyticsView({ calls, chats, agents }: { calls: DashboardDataset["calls"]; chats: DashboardDataset["chats"]; agents: DashboardDataset["agents"] }) {
  const [tab, setTab] = useState<"calls"|"chats">("calls"); const [agent, setAgent] = useState("all");
  const filteredCalls = calls.filter((row) => agent === "all" || row.agentId === agent); const filteredChats = chats.filter((row) => agent === "all" || row.agentId === agent);
  const rows = tab === "calls" ? filteredCalls : filteredChats; const breakdown = agents.map((item) => ({ name: item.name.length > 18 ? `${item.name.slice(0,18)}…` : item.name, sessions: tab === "calls" ? filteredCalls.filter((row) => row.agentId === item.id).length : filteredChats.filter((row) => row.agentId === item.id).length }));
  const success = rows.filter((row) => /success|book|resolved|qualified/i.test(row.outcome)).length;
  return <div className="space-y-5"><div className="glass rounded-2xl p-5"><div className="flex flex-wrap items-center gap-3"><button onClick={() => setTab("calls")} className={`border-b-2 px-3 py-2 font-semibold ${tab==="calls"?"border-[#253246]":"border-transparent text-[#84928d]"}`}>Call Dashboard</button><button onClick={() => setTab("chats")} className={`border-b-2 px-3 py-2 font-semibold ${tab==="chats"?"border-[#253246]":"border-transparent text-[#84928d]"}`}>Chat Dashboard</button><select value={agent} onChange={(e) => setAgent(e.target.value)} className={`${control} ml-auto`}><option value="all">All agents</option>{agents.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></div></div><div className="grid gap-4 sm:grid-cols-3"><Metric label="Total sessions" value={String(rows.length)}/><Metric label="Successful outcomes" value={String(success)}/><Metric label="Success rate" value={`${rows.length ? Math.round(success/rows.length*100) : 0}%`}/></div><div className="glass rounded-2xl p-6"><h3 className="font-semibold">Sessions by agent</h3><div className="mt-5 h-72"><ResponsiveContainer width="100%" height="100%"><BarChart data={breakdown}><CartesianGrid vertical={false} stroke="#173f3312"/><XAxis dataKey="name" tick={{fontSize:11}}/><YAxis allowDecimals={false}/><Tooltip/><Bar dataKey="sessions" fill="#1f7659" radius={[6,6,0,0]}/></BarChart></ResponsiveContainer></div></div></div>;
}

function Metric({ label, value }: { label: string; value: string }) { return <article className="glass rounded-2xl p-6"><p className="text-sm text-[#71817c]">{label}</p><p className="mt-2 text-3xl font-semibold">{value}</p></article>; }
function Empty({ children }: { children: React.ReactNode }) { return <div className="p-12 text-center text-sm text-[#84928d]">{children}</div>; }
function downloadCsv(filename: string, rows: unknown[]) { const records = rows as Record<string, unknown>[]; const first = records[0]; if (!first) return; const keys = Object.keys(first); const csv = [keys.join(","), ...records.map((row) => keys.map((key) => JSON.stringify(row[key] ?? "")).join(","))].join("\n"); const url = URL.createObjectURL(new Blob([csv], { type: "text/csv" })); const link = document.createElement("a"); link.href=url; link.download=filename; link.click(); URL.revokeObjectURL(url); }
